# first.moph — 丸が右へ動き、四角が横に広がり、文字が現れて、最後に消える

import { fade_out } from animation

let v = View(box = Vector(16, 9))
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #f4f1ea))

# 動かす 3 つは 1 つの箱にまとめる。まとめて薄くできる
let stage = View(box = Vector(16, 9), opacity = 1)
v.place(stage, at = Pos(0, 0, anchor = :topLeft), w = 16)

let ball = Circle(position = Pos(3, 2.5), radius = 1, fill = #e0604a)
let bar = Rect(position = Pos(2, 8, anchor = :bottomLeft), w = 0.5, h = 2, fill = #3a6fb0)
let label = TextArea(text = "mophila", position = Pos(8, 5), fontSize = 1.2, fill = #222222, opacity = 0)
stage.place(ball)
stage.place(bar)
stage.place(label)

# 丸は 3 秒かけて右へ。ease で加速して減速する
let move = context ball as b {
  motion (t) {
    0s: b.position.x = 3
    3s: b.position.x = 13 :ease
  }
}

# 四角は 2 秒で横に広がる
let widen = context bar as r {
  motion (t) {
    0s: r.w = 0.5
    2s: r.w = 12 :ease_out
  }
}

# 文字は 1 秒で現れる
let appear = context label as l {
  motion (t) {
    0s: l.opacity = 0
    1s: l.opacity = 1
  }
}

let track = Timeline()
track.place(move, at = 0s)
track.place(widen, at = 0.5s)
track.place(appear, at = 3s)
# 文字が出そろう 4s から 3 秒見せて、最後の 1 秒で箱ごと消える
track.place(fade_out(stage, 1s), at = 7s)
v.addTrack(track)
output v

# shapes.moph — 丸は動きながら大きさが変わり、四角は回り、五角形は頂点そのものが波打つ

import math
import { regular_polygon } from shape

let v = View(box = Vector(16, 9))
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #f5f4f0))

let total = 6s
let cx = 8
let swing = 3.2
let track = Timeline()

# 丸。止まる、動く、止まる。行末の :ease で動き出しと止まり際がなめらかになる
let ball = Circle(position = Pos(cx - swing, 2.5), radius = 0.65, fill = #e0604a)
v.place(ball)
let roll = context ball as c {
  motion (t) {
    0:    c.position.x = cx - swing, c.radius = 0.65
    0.15: c.position.x = cx - swing, c.radius = 0.65
    0.5:  c.position.x = cx + swing, c.radius = 1.25 :ease
    0.65: c.position.x = cx + swing, c.radius = 1.25
    1:    c.position.x = cx - swing, c.radius = 0.65 :ease
  }
}
roll.duration = total
track.place(roll, at = 0s)

# 四角。rotation は時計回りの角度。中心は囲む四角形の中心で、pivot を書けばそこを軸にできる
let square = Polygon(points = regular_polygon(cx, 4.6, 0.95, 4), fill = #3a6fb0)
v.place(square)
let spin = context square as s {
  motion (t) {
    0: s.rotation = 0
    1: s.rotation = 360
  }
}
spin.duration = total
track.place(spin, at = 0s)

# 五角形。頂点ごとに中心からの距離を変えて、うねらせる。0..1 の行は毎フレーム評価される
let py = 6.7
let penta = Polygon(points = regular_polygon(cx, py, 0.95, 5), fill = #3f9b6d)
v.place(penta)
let wobble = context penta as p {
  motion (t) {
    0..1: p.points = (0..5).to_list().map(func (i) {
      let a = (i * 72 - 90) * math.PI / 180
      let r = 0.95 + 0.3 * math.sin(math.TAU * t * 2 + i * 1.5)
      Vector(cx + r * math.cos(a), py + r * math.sin(a))
    })
  }
}
wobble.duration = total
track.place(wobble, at = 0s)

v.addTrack(track)
output v

# bounce.moph — 色の違うボールが順に落ちて弾み、8 秒後に逆再生で戻る。落下は ease_in (加速)、上昇は ease_out (減速)

let v = View(box = Vector(16, 9))
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #1c1c24))
let floor = 7.8
v.place(Line(from = Vector(0, floor), to = Vector(16, floor), stroke = #50505a, strokeWidth = 0.05))

let colors = [#e04040, #e0a020, #40a060, #4080e0, #a060e0]
let track = Timeline()

# 1 個分の落下と 3 回のバウンド。高さは 1 回ごとに 55% に減る
func drop(ball, r) {
  let top = 1 + r
  let ground = floor - r
  let h1 = (ground - top) * 0.55
  let h2 = h1 * 0.55
  let h3 = h2 * 0.55
  context ball as b {
    motion (t) {
      0s:   b.position.y = top
      1s:   b.position.y = ground            :ease_in
      1.6s: b.position.y = ground - h1       :ease_out
      2.2s: b.position.y = ground            :ease_in
      2.6s: b.position.y = ground - h2       :ease_out
      3s:   b.position.y = ground            :ease_in
      3.25s: b.position.y = ground - h3      :ease_out
      3.5s: b.position.y = ground            :ease_in
    }
  }
}

# 着地の瞬間だけ影を濃くする
func shadow_pulse(shadow) {
  context shadow as s {
    motion (t) {
      0s:   s.opacity = 0.15
      1s:   s.opacity = 0.6
      1.3s: s.opacity = 0.2
      2.2s: s.opacity = 0.5
      2.5s: s.opacity = 0.2
      3s:   s.opacity = 0.4
      3.5s: s.opacity = 0.25
    }
  }
}

for (i, color) in colors.enumerate() {
  let r = 0.45 + i * 0.05
  let x = 2.5 + i * 2.75
  let shadow = Rect(position = Pos(x, floor), w = r * 2.4, h = 0.12, fill = #000000, opacity = 0.15)
  let ball = Circle(position = Pos(x, 1 + r), radius = r, fill = color)
  v.place(shadow)
  v.place(ball)
  let fall = drop(ball, r)
  let pulse = shadow_pulse(shadow)
  track.place(fall, at = i * 0.3s)
  track.place(pulse, at = i * 0.3s)
  # 逆再生。reverse は区間ごとの ease_in / ease_out を入れ替える
  track.place(fall.reverse(), at = 8s + i * 0.3s)
  track.place(pulse.reverse(), at = 8s + i * 0.3s)
}

let title = TextArea(text = "bounce", position = Pos(0.5, 0.3, anchor = :topLeft), fontSize = 0.6, fill = #d0d0d8)
v.place(title)

v.addTrack(track)
output v

# bars.moph — 棒グラフが順に伸び、値のラベルが後から現れる

import { fade_in } from animation

let v = View(box = Vector(16, 9))
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #f7f7f2))

let title = TextArea(text = "Monthly visitors", position = Pos(1, 0.6, anchor = :topLeft), fontSize = 0.7, fill = #202020, opacity = 0)
v.place(title)

# 軸
let x_axis = Line(from = Vector(1.5, 7.5), to = Vector(15, 7.5), stroke = #808080, strokeWidth = 0.03, opacity = 0)
let y_axis = Line(from = Vector(1.5, 2), to = Vector(1.5, 7.5), stroke = #808080, strokeWidth = 0.03, opacity = 0)
v.place(x_axis)
v.place(y_axis)

let data = [
  { "label": "Jan", "value": 32, "color": #4080e0 },
  { "label": "Feb", "value": 48, "color": #4080e0 },
  { "label": "Mar", "value": 41, "color": #4080e0 },
  { "label": "Apr", "value": 65, "color": #40a060 },
  { "label": "May", "value": 80, "color": #40a060 },
  { "label": "Jun", "value": 74, "color": #e0a020 },
]
let max = 100
let chart_h = 5
let bar_w = 1.4
let gap = 0.8

let track = Timeline()

track.place(fade_in(title, 0.6s), at = 0s)
track.place(fade_in(x_axis, 0.6s), at = 1s)
track.place(fade_in(y_axis, 0.6s), at = 1s)

# 棒は下端を固定 (bottom を基準点にする) して h だけ伸ばす
func grow(bar, h, delay) {
  let tl = context bar as b {
    motion (t) {
      0s: b.h = 0.01
      1.5s: b.h = h :ease_out
    }
  }
  track.place(tl, at = delay)
}

for (i, d) in data.enumerate() {
  let x = 2.2 + i * (bar_w + gap)
  let h = chart_h * d["value"] / max
  let bar = Rect(position = Pos(x + bar_w / 2, 7.5, anchor = :bottom), w = bar_w, h = 0.01, fill = d["color"])
  v.place(bar)
  grow(bar, h, 2s + i * 0.9s)

  let name = TextArea(text = d["label"], position = Pos(x + bar_w / 2, 7.7, anchor = :top), fontSize = 0.4, fill = #404040, align = :center)
  v.place(name)

  let value = TextArea(text = "{v}".format(d["value"]), position = Pos(x + bar_w / 2, 7.5 - h - 0.15, anchor = :bottom), fontSize = 0.4, fill = #202020, align = :center, opacity = 0)
  v.place(value)
  track.place(fade_in(value, 0.4s), at = 2s + i * 0.9s + 1.5s)

  # 最大の棒は最後に色を変えて強調する
  if d["value"] == 80 {
    track.place(context bar as b {
      motion (t) {
        0s:   b.fill = d["color"]
        0.8s: b.fill = #e04040 :ease
      }
    }, at = 10.5s)
  }
}

v.addTrack(track)
output v

# orbit.moph — 太陽系。惑星が異なる半径・周期で公転し、月が地球を回る

import math

let v = View(box = Vector(16, 9))
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #101020))

let cx = 8
let cy = 4.5

# 太陽。脈動は 3 つのキーフレーム
let sun = Circle(position = Pos(cx, cy), radius = 0.9, fill = #f0c040)
v.place(sun)
let pulse = context sun as s {
  motion (t) {
    0:   s.radius = 0.9
    0.5: s.radius = 1.05 :ease
    1:   s.radius = 0.9  :ease
  }
}
pulse.duration = 4s

# 円軌道。0..1 の区間で式を毎フレーム評価するので、t が 0→1 で 1 周する。period で速さを決める
func orbit(body, r, period) {
  let tl = context body as b {
    motion (t) {
      0..1: b.position = Pos(cx + r * math.cos(math.TAU * t), cy + r * math.sin(math.TAU * t))
    }
  }
  tl.duration = period
  tl
}

let planets = [
  { "r": 1.6, "size": 0.16, "period": 3s,  "color": #c0c0c0 },
  { "r": 2.5, "size": 0.26, "period": 5s,  "color": #e0a060 },
  { "r": 3.4, "size": 0.28, "period": 8s,  "color": #4080e0 },
  { "r": 4.2, "size": 0.20, "period": 12s, "color": #e05040 },
]

# 軌道の線 (fill なし、stroke だけの Circle)
for p in planets {
  v.place(Circle(position = Pos(cx, cy), radius = p["r"], stroke = #303050, strokeWidth = 0.02))
}

let total = 15s
let track = Timeline(duration = total)
for i in 0..4 {
  track.place(pulse, at = i * 4s)
}

for p in planets {
  let body = Circle(position = Pos(cx + p["r"], cy), radius = p["size"], fill = p["color"])
  v.place(body)
  # 公転を total の間繰り返す
  let tl = orbit(body, p["r"], p["period"])
  let n = total / p["period"]
  for i in 0..math.ceil(n) {
    track.place(tl, at = i * p["period"])
  }
}

# 地球 (r = 3.4, 8 秒で 1 周) の月。地球の位置に、6 倍速の小さな円運動を足す
let moon = Circle(position = Pos(cx + 3.4 + 0.5, cy), radius = 0.08, fill = #d0d0d0)
v.place(moon)
let moon_tl = context moon as m {
  motion (t) {
    0..1: m.position = Pos(cx + 3.4 * math.cos(math.TAU * t) + 0.5 * math.cos(math.TAU * t * 6), cy + 3.4 * math.sin(math.TAU * t) + 0.5 * math.sin(math.TAU * t * 6))
  }
}
moon_tl.duration = 8s
track.place(moon_tl, at = 0s)
track.place(moon_tl, at = 8s)
track.place(moon_tl, at = 16s)

let title = TextArea(text = "orbit", position = Pos(0.4, 0.3, anchor = :topLeft), fontSize = 0.6, fill = #e0e0f0)
v.place(title)
track.place(context title as o {
  motion (t) {
    0s:   o.opacity = 0
    1.5s: o.opacity = 1
  }
}, at = 0s)

v.addTrack(track)
output v

# fractal.moph — 枝分かれする木。各枝は親の先端から生え、親が動けば子も動く
# 部品が互いに依存する形: 枝の行は毎フレーム親の to を読む (0..1 の範囲行)。木は根から順に伸び、伸び切ったら風に揺れる

import math

let v = View(box = Vector(16, 9))
let track = Timeline()
v.place(Rect(position = Pos(0, 0, anchor = :topLeft), w = 16, h = 9, fill = #0d1117))

# ---------- 形と時間の決まり ----------
let levels     = 8            # 枝分かれの回数 (枝は 2^(levels+1) - 1 本)
let total      = 14s          # 動画の長さ
let trunk_len  = 2.1
let shrink     = 0.72         # 1 段ごとの長さの比
let spread     = 0.46         # 枝の開き (rad)
let grow_time  = 0.9          # 1 段が伸びる秒数
let grow_gap   = 0.5          # 次の段が伸び始めるまでの秒数
let sway_amp   = 0.035        # 揺れの角度 (rad)。先端ほど大きい
let sway_period = 4.5         # 揺れの周期 (秒)
let colors = [#7a4f33, #8a5c3a, #97693f, #8c7a42, #7c8c45, #62984c, #4aa25a, #46ad78, #6cc496]

let seconds = total / 1s      # t は 0..1 なので、秒に直すときに掛ける

func smooth(k) { k * k * (3 - 2 * k) }

# level 段目の枝が t (0..1) の時点でどこまで伸びているか (0..1)
func growth(t, level) {
  let k = (t * seconds - level * grow_gap) / grow_time
  smooth(math.min(1, math.max(0, k)))
}

# 揺れ。段が深いほど大きく、phase で枝ごとにずらす
func sway(t, level, phase) {
  sway_amp * level * math.sin(t * seconds / sway_period * math.TAU + phase)
}

func direction(angle) { Vector(math.cos(angle), -math.sin(angle)) }

# 親の先端から角度 angle に伸びる枝を作り、その先にさらに 2 本作る
func branch(parent, angle, len, level, phase) {
  let line = Line(from = Vector(0, 0), to = Vector(0, 0), stroke = colors[level], strokeWidth = 0.18 * shrink ^ level, opacity = 0.95)
  v.place(line)
  let tl = context line as b, parent as p {
    motion (t) {
      0..1: b.from = p.to
      0..1: b.to = p.to + direction(angle + sway(t, level, phase)) * (len * growth(t, level))
    }
  }
  tl.duration = total
  track.place(tl)
  if level < levels {
    branch(line, angle + spread, len * shrink, level + 1, phase + 0.4)
    branch(line, angle - spread, len * shrink, level + 1, phase - 0.4)
  } else {
    # 先端の葉。枝が伸び切ってから出る
    let leaf = Circle(position = Pos(0, 0), radius = 0.06, fill = #b9e88a, opacity = 0)
    v.place(leaf)
    let ltl = context leaf as f, line as b {
      motion (t) {
        0..1: f.position = Pos(b.to)
        0..1: f.opacity = growth(t, level + 1) * 0.9
      }
    }
    ltl.duration = total
    track.place(ltl)
  }
}

# 幹は地面から。先端は伸びるだけで揺れない
let root = Vector(8, 8.6)
let trunk = Line(from = root, to = root, stroke = colors[0], strokeWidth = 0.18, opacity = 0.95)
v.place(trunk)
let trunk_tl = context trunk as b {
  motion (t) {
    0..1: b.to = root + direction(math.PI / 2) * (trunk_len * growth(t, 0))
  }
}
trunk_tl.duration = total
track.place(trunk_tl)
branch(trunk, math.PI / 2 + spread, trunk_len * shrink, 1, 0.4)
branch(trunk, math.PI / 2 - spread, trunk_len * shrink, 1, -0.4)

v.addTrack(track)
output v

# walker.moph — 歩く人。関節ごとの図形が、親の先端を毎フレーム読んでつながる (腰 → 腿 → 脛 → 足、肩 → 上腕 → 前腕)。
# 歩行の周期は sin で作る。脚が前に振れるとき膝が曲がり、着いているときは伸びる。腕は同じ側の脚と逆に振る。
# make(near, far, long) が「その場で long の間歩く人」の View (箱 6 x 6、足元は y 5.6) を返す。import して並べられる。
# 進むのは置いた側の仕事で、箱の幅 6 のとき 1 秒に speed 進めると足が滑らない

import math

# ---------- 体の寸法と歩き方 ----------
export let period = 1.2    # 1 周期 (左右 1 歩ずつ) の秒数
export let speed  = 3.1    # 歩幅に合う進む速さ (箱の単位 / 秒)
export let floor  = 5.6    # 箱の中の足元の高さ
let thigh   = 1.4
let shin    = 1.3
let torso   = 1.6
let upper   = 1.1
let fore    = 1.0
let swing   = 0.35         # 腿の振れ幅 (rad)
let width   = 0.13

# 角度 0 が真下、正が前 (x が増える向き)
func direction(a) { Vector(math.sin(a), math.cos(a)) }
# 歩行の位相。side は 0 (手前) か 1 (奥) で半周期ずれる
func phase(t, side, long) { math.TAU * t * (long / 1s) / period + side * math.PI }
func hip_at(t, long) { Vector(3, floor - thigh - shin + 0.15 - 0.07 * math.cos(2 * phase(t, 0, long))) }
func thigh_angle(p) { swing * math.sin(p) }
# 前に振れている間 (cos > 0) だけ膝を曲げる
func shin_angle(p) { thigh_angle(p) - 0.1 - 0.9 * math.max(0, math.cos(p)) }
func upper_angle(p) { -0.6 * math.sin(p) }
func fore_angle(p) { upper_angle(p) + 0.55 }

func limb(box, color) {
  let l = Line(from = Vector(0, 0), to = Vector(0, 0), stroke = color, strokeWidth = width)
  box.place(l)
  l
}
func joint(box, color, r) {
  let c = Circle(position = Pos(0, 0), radius = r, fill = color)
  box.place(c)
  c
}

# 片側の脚と腕。親の先端を読む行でつなぐ。戻り値は Timeline
func side_of(box, side, color, long) {
  let th = limb(box, color)
  let sh = limb(box, color)
  let ft = limb(box, color)
  let ua = limb(box, color)
  let fa = limb(box, color)
  let knee = joint(box, color, width / 2)
  let ankle = joint(box, color, width / 2)
  let elbow = joint(box, color, width / 2)
  let hand = joint(box, color, width * 0.7)
  let tl = context th as a, sh as b, ft as c, ua as d, fa as e, knee as k, ankle as n, elbow as m, hand as h {
    motion (t) {
      0..1: a.from = hip_at(t, long)
      0..1: a.to = a.from + direction(thigh_angle(phase(t, side, long))) * thigh
      0..1: b.from = a.to
      0..1: b.to = b.from + direction(shin_angle(phase(t, side, long))) * shin
      0..1: c.from = b.to
      0..1: c.to = c.from + direction(shin_angle(phase(t, side, long)) + math.PI / 2) * 0.35
      0..1: k.position = Pos(a.to)
      0..1: n.position = Pos(b.to)
      0..1: d.from = hip_at(t, long) + Vector(0.12, -torso)
      0..1: d.to = d.from + direction(upper_angle(phase(t, side, long))) * upper
      0..1: e.from = d.to
      0..1: e.to = e.from + direction(fore_angle(phase(t, side, long))) * fore
      0..1: m.position = Pos(d.to)
      0..1: h.position = Pos(e.to)
    }
  }
  tl.duration = long
  tl
}

# その場で long の間歩く人。near は手前の手足と胴の色、far は奥の手足の色
export func make(near: Color, far: Color, long: Duration) -> View {
  let box = View(box = Vector(6, 6))
  let tl = Timeline()
  # 奥 → 胴 → 手前 の順に置き、同じ順に当てる (親の値を読む行は、親の行が先に当たっている必要がある)
  tl.place(side_of(box, 1, far, long), at = 0s)
  let body = limb(box, near)
  let hip = joint(box, near, width * 0.8)
  let neck = joint(box, near, width / 2)
  let head = joint(box, near, 0.36)
  let trunk = context body as b, hip as p, neck as n, head as h {
    motion (t) {
      0..1: b.from = hip_at(t, long)
      0..1: b.to = b.from + Vector(0.12, -torso)
      0..1: p.position = Pos(b.from)
      0..1: n.position = Pos(b.to)
      0..1: h.position = Pos(b.to + Vector(0.08, -0.5))
    }
  }
  trunk.duration = long
  tl.place(trunk, at = 0s)
  tl.place(side_of(box, 0, near, long), at = 0s)
  box.addTrack(tl)
  box
}

